import { useState, type FormEvent } from 'react';
import { JxButton, JxDivider, JxInputField, JxSelect, JxSwitch } from '@jinx-ui/react';

export interface ProfileSettings {
  name: string;
  language: string;
  emailNotifications: boolean;
}

export interface ProfileSettingsFormProps {
  initialSettings?: Partial<ProfileSettings>;
  onSave: (settings: ProfileSettings) => void;
}

export default function ProfileSettingsForm({ initialSettings, onSave }: ProfileSettingsFormProps) {
  const [name, setName] = useState(initialSettings?.name ?? '');
  const [language, setLanguage] = useState(initialSettings?.language ?? 'ru');
  const [emailNotifications, setEmailNotifications] = useState(initialSettings?.emailNotifications ?? false);
  const [nameError, setNameError] = useState('');

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const trimmed = name.trim();
    if (!trimmed) {
      setNameError('Укажите имя');
      return;
    }
    setNameError('');
    onSave({ name: trimmed, language, emailNotifications });
  };

  return (
    <form
      onSubmit={submit}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px',
        padding: '20px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <JxInputField
        label="Имя"
        required
        value={name}
        placeholder="Как к вам обращаться"
        onChange={(event) => setName(event.target.value)}
        errorText={nameError}
      />

      <JxSelect
        label="Язык интерфейса"
        placeholder="Выберите язык"
        options={[
          { value: 'ru', label: 'Русский' },
          { value: 'en', label: 'English' },
        ]}
        value={language}
        onValueChange={setLanguage}
      />

      <JxSwitch
        label="Уведомления на почту"
        checked={emailNotifications}
        onChange={(event) => setEmailNotifications(event.target.checked)}
      />

      <JxDivider />

      <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
        <JxButton type="submit" variant="primary">
          Сохранить
        </JxButton>
      </div>
    </form>
  );
}

